WRenewalCount.code:
// AI duration in Months, only where CLM is empty: CLMAgreementDetails.RenewalTerm <- renewal.term.Value (ISO 8601: P12M, P1Y, P90D, P2W)
var cur = Convert.ToString(GetVariableValue("DocXml.Documents.Document.CLMAgreementDetails.RenewalTerm")).Trim();
var ai = Convert.ToString(GetVariableValue("AiInsights.AIExtractions.FlattenedFieldCollections.renewal.term.Value")).Trim();
if (cur != "" || ai.Length < 3 || !ai.StartsWith("P") || ai.Contains("T")) return "";
var u = ai.Substring(ai.Length - 1);
var n = Convert.ToInt32(ai.Substring(1, ai.Length - 2));
if (u == "M") return Convert.ToString(n);
if (u == "Y") return Convert.ToString(n * 12);
return "";

WNoticeCount.code:
// AI duration in Days, only where CLM is empty: CLMAgreementDetails.RenewalNoticePeriod <- renewal.noticePeriod.Value (ISO 8601: P12M, P1Y, P90D, P2W)
var cur = Convert.ToString(GetVariableValue("DocXml.Documents.Document.CLMAgreementDetails.RenewalNoticePeriod")).Trim();
var ai = Convert.ToString(GetVariableValue("AiInsights.AIExtractions.FlattenedFieldCollections.renewal.noticePeriod.Value")).Trim();
if (cur != "" || ai.Length < 3 || !ai.StartsWith("P") || ai.Contains("T")) return "";
var u = ai.Substring(ai.Length - 1);
var n = Convert.ToInt32(ai.Substring(1, ai.Length - 2));
if (u == "D") return Convert.ToString(n);
if (u == "W") return Convert.ToString(n * 7);
if (u == "M") return Convert.ToString(n * 30);
return "";

